+package com.salesmanager.shop.store.controller.shoppingCart.facade;
+
+import javax.inject.Inject;
+
+import org.apache.commons.lang3.StringUtils;
+import org.springframework.stereotype.Service;
+
+import com.salesmanager.core.business.exception.ServiceException;
+import com.salesmanager.core.business.services.system.MerchantConfigurationService;
+import com.salesmanager.core.model.merchant.MerchantStore;
+import com.salesmanager.core.model.system.MerchantConfiguration;
+import com.salesmanager.shop.store.api.exception.ServiceRuntimeException;
+
+@Service
+public class CartQuantityLimitService {
+
+    public static final String CART_MAX_LINE_QUANTITY = \"CART_MAX_LINE_QUANTITY\";
+    public static final int DEFAULT_MAX_LINE_QUANTITY = 99;
+
+    private final MerchantConfigurationService merchantConfigurationService;
+
+    @Inject
+    public CartQuantityLimitService(MerchantConfigurationService merchantConfigurationService) {
+        this.merchantConfigurationService = merchantConfigurationService;
+    }
+
+    public int getMaxLineQuantity(MerchantStore store) {
+        try {
+            MerchantConfiguration configuration = merchantConfigurationService
+                    .getMerchantConfiguration(CART_MAX_LINE_QUANTITY, store);
+            if (configuration == null || StringUtils.isBlank(configuration.getValue())) {
+                return DEFAULT_MAX_LINE_QUANTITY;
+            }
+            return Integer.parseInt(configuration.getValue());
+        } catch (ServiceException e) {
+            throw new ServiceRuntimeException(\"Unable to read cart quantity limit\", e);
+        } catch (NumberFormatException e) {
+            throw new ServiceRuntimeException(\"Invalid \" + CART_MAX_LINE_QUANTITY + \" configuration\", e);
+        }
+    }
+
+    public void validateQuantity(int quantity, MerchantStore store) {
+        int maximum = getMaxLineQuantity(store);
+        if (quantity > 0 && quantity > maximum) {
+            throw new ServiceRuntimeException(
+                    \"Cart line quantity \" + quantity + \" exceeds maximum \" + maximum);
+        }
+    }
+}
